        arr[i], _ = strconv.Atoi(scanner.Text())
        if i != 0 {
            arr[i] += arr[i - 1]
        }
    }

    /* 
    区间[l, r]的和可以使用区间[0, r]和[0, l - 1]相减得到，
    在代码中即为arr[r]-arr[l-1]。这里需要注意l-1是否越界
    */
    for {
        var l, r int
        scanner.Scan()
        _, err := fmt.Sscanf(scanner.Text(), "%d %d", &l, &r)
        if err != nil {
            return
        }

        if l > 0 {
            fmt.Println(arr[r] - arr[l - 1])
        } else {
            fmt.Println(arr[r])
        }
    }
}
